ids=[x for x in ids if re.fullmatch('chr([1-9]|1[0-9]|2[0-2])',m['coordinates'][x][0])]
rc=lambda s:s.translate(str.maketrans('ACGT','TGCA'))[::-1]
parent={x:x for x in ids}
def root(x):
 while parent[x]!=x:parent[x]=parent[parent[x]];x=parent[x]
 return x
def union(a,b):
 a,b=root(a),root(b)
 if a!=b:parent[max(a,b)]=min(a,b)
km={x:{min(s,rc(s)) for s in [m['sequences'][x][i:i+21] for i in range(len(m['sequences'][x])-20)]} for x in ids}
links=[]
for i,a in enumerate(ids):
 ca=m['coordinates'][a];sa=m['sequences'][a]
 for b in ids[:i]:
  cb=m['coordinates'][b];sb=m['sequences'][b];reason=[]
  if ca[0]==cb[0] and ca[1]//1000000==cb[1]//1000000:reason.append('same_1Mb_block')
  if ca[0]==cb[0] and max(ca[1],cb[1])<min(ca[2],cb[2]):reason.append('coordinate_overlap')
  if min(sa,rc(sa))==min(sb,rc(sb)):reason.append('exact_or_reverse_complement')
  if km[a] and km[b] and len(km[a]&km[b])/min(len(km[a]),len(km[b]))>=.2:reason.append('21mer_containment_ge_0.2')
  if reason:union(a,b);links.append(dict(a=a,b=b,reasons=reason))
